using System;
using System.IO;
using System.Linq;
using System.Diagnostics;
using System.Collections.Generic;
using System.Drawing;
using System.Windows.Forms;
using System.ComponentModel;
using Microsoft.Win32;

namespace CrossHermit {
 public static class UninstallProgram {
  public static object Remove(string root,string backup,bool integrations){root=Core.Full(root);backup=Core.Full(backup);Core.ValidateRoot(root);Core.AssertGameClosed();Core.NoLinks(backup);if(Core.Same(backup,root)||Core.Inside(backup,root)||Core.Inside(root,backup))throw new IOException("The backup must be outside the installation.");string marker=Path.Combine(root,"EnglishPatch/install-owned.json");var ownership=Core.Read(marker);if(Convert.ToString(ownership["product"])!=Core.Product||!Core.Same(Convert.ToString(ownership["install_root"]),root))throw new IOException("The installation ownership record does not match this folder.");var owned=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(object n in (System.Collections.IEnumerable)ownership["files"]){string p=Core.Child(root,Convert.ToString(n));if(!owned.Add(Core.Relative(root,p)))throw new IOException("Duplicate installation file record.");}if(!owned.Contains("Launcher.exe")||!owned.Contains("Uninstall.exe")||!owned.Contains("Cross Hermit.exe"))throw new IOException("The ownership record is incomplete.");if(Directory.Exists(backup)&&Directory.GetFileSystemEntries(backup).Length!=0)throw new IOException("The backup folder is not empty.");
   string lockPath=Path.Combine(root,"EnglishPatch/update.lock");var saved=new Dictionary<string,object>();var all=new List<string>();using(var held=new FileStream(lockPath,FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){
    all=Core.Files(root).Where(p=>!Core.Same(p,lockPath)).ToList();Directory.CreateDirectory(backup);
    foreach(string p in all){string n=Core.Relative(root,p);if(Core.Personal(n)||!owned.Contains(n)){string dest=Core.Child(backup,n);Directory.CreateDirectory(Path.GetDirectoryName(dest));string h=Core.Hash(p);File.Copy(p,dest,false);if(Core.Hash(dest)!=h)throw new IOException("Backup verification failed: "+n);saved[n]=new {sha256=h,bytes=new FileInfo(p).Length};}}
    Core.Write(Path.Combine(backup,"SAVE-BACKUP.json"),new {product=Core.Product,source=root,created_utc=DateTime.UtcNow.ToString("o"),files=saved});
    Core.AssertGameClosed();foreach(string f in all){using(var probe=new FileStream(f,FileMode.Open,FileAccess.Read,FileShare.None)){} }foreach(var row in saved){string n=row.Key;/* Verify the source did not change during the backup. */if(Core.Hash(Core.Child(root,n))!=Core.Hash(Core.Child(backup,n)))throw new IOException("A personal file changed during backup; uninstall was stopped.");}
    foreach(string p in all){Core.NoLinks(p);File.SetAttributes(p,File.GetAttributes(p)&~FileAttributes.ReadOnly);File.Delete(p);}
   }
   if(File.Exists(lockPath))File.Delete(lockPath);
   var dirs=new List<string>();var stack=new Stack<string>();stack.Push(root);while(stack.Count>0){string d=stack.Pop();Core.NoLinks(d);dirs.Add(d);foreach(string child in Directory.GetDirectories(d)){Core.NoLinks(child);stack.Push(child);}}foreach(string d in dirs.OrderByDescending(p=>p.Length)){if(Directory.GetFileSystemEntries(d).Length!=0)throw new IOException("Unexpected files remain. They were kept at "+d);Directory.Delete(d);}
   if(integrations)RemoveIntegrations(root);
   return new {passed=true,product=Core.Product,removed_root=root,backup=backup,preserved_files=saved.Count,deleted_files=all.Count,game_started=false};
  }
  static void RemoveIntegrations(string root){using(var k=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Uninstall\CrossHermitEnglish")){if(k!=null&&Core.Same(Convert.ToString(k.GetValue("InstallLocation","")),root))Registry.CurrentUser.DeleteSubKeyTree(@"Software\Microsoft\Windows\CurrentVersion\Uninstall\CrossHermitEnglish",false);}using(var k=Registry.CurrentUser.OpenSubKey(@"Software\Enterbrain\Cross Hermit")){if(k!=null&&Core.Same(Convert.ToString(k.GetValue("InstallPath","")),root))Registry.CurrentUser.DeleteSubKeyTree(@"Software\Enterbrain\Cross Hermit",false);}
   Type t=Type.GetTypeFromProgID("WScript.Shell");dynamic shell=Activator.CreateInstance(t);string desktop=Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),menu=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),"Cross Hermit English");var links=new List<string>{Path.Combine(desktop,"Cross Hermit English.lnk")};if(Directory.Exists(menu))links.AddRange(Directory.GetFiles(menu,"*.lnk"));foreach(string p in links){if(!File.Exists(p))continue;dynamic l=shell.CreateShortcut(p);string target=Convert.ToString(l.TargetPath),args=Convert.ToString(l.Arguments);if(Core.Inside(target,root)||args.IndexOf(root+"\\",StringComparison.OrdinalIgnoreCase)>=0){Core.NoLinks(p);File.Delete(p);}}if(Directory.Exists(menu)&&Directory.GetFileSystemEntries(menu).Length==0)Directory.Delete(menu);
  }
  [STAThread]public static int Main(string[] a){string result=Core.Arg(a,"--result",null);bool quiet=Core.Has(a,"--quiet");try{Application.EnableVisualStyles();string root=Core.Arg(a,"--remove-root",AppDomain.CurrentDomain.BaseDirectory);root=Core.Full(root);Core.ValidateRoot(root);Core.AssertGameClosed();string backup=Core.Arg(a,"--backup",Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"Cross Hermit Backups","Uninstall-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,8)));
   if(!Core.Has(a,"--remove-root")){if(!quiet&&MessageBox.Show("Remove Cross Hermit English?\n\nYour saves, settings and unrecognized files will be copied and verified here first:\n"+backup,"Uninstall Cross Hermit",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return 0;string temp=Path.Combine(Path.GetTempPath(),"CH-uninstall-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);string exe=Path.Combine(temp,"Uninstall.exe");File.Copy(Application.ExecutablePath,exe);string args="--remove-root "+Core.Quote(root)+" --backup "+Core.Quote(backup)+" --wait-pid "+Process.GetCurrentProcess().Id+(quiet?" --quiet":"")+(result!=null?" --result "+Core.Quote(result):"");Process.Start(new ProcessStartInfo(exe,args){WorkingDirectory=temp,UseShellExecute=false,CreateNoWindow=true});return 0;}
   if(Core.Inside(Application.ExecutablePath,root))throw new IOException("Uninstall must run from its temporary copy.");int pid=Int32.Parse(Core.Arg(a,"--wait-pid","0"));if(pid>0){try{using(var parent=Process.GetProcessById(pid))if(!parent.WaitForExit(30000))throw new IOException("Close the first uninstaller window and try again.");}catch(ArgumentException){}}
   if(quiet){object report=Remove(root,backup,!Core.Has(a,"--no-integrations"));if(result!=null)Core.Write(result,report);return 0;}
   using(var progress=new UninstallForm(root,backup,result,!Core.Has(a,"--no-integrations")))Application.Run(progress);return 0;
  }catch(Exception e){if(result!=null)Core.Write(result,new {passed=false,error=e.Message,game_started=false});if(!quiet)MessageBox.Show(e.Message,"Cross Hermit Uninstall",MessageBoxButtons.OK,MessageBoxIcon.Error);return 1;}}
 }
 public sealed class UninstallForm:Form {
  bool done;Label status=new Label();Button close=new Button();BackgroundWorker worker=new BackgroundWorker();
  public UninstallForm(string root,string backup,string result,bool integrations){Text="Uninstall Cross Hermit";ClientSize=new Size(560,195);Font=new Font("Segoe UI",10);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;StartPosition=FormStartPosition.CenterScreen;status.Text="Backing up and verifying your saves and settings, then removing the game...";status.SetBounds(18,18,524,100);Controls.Add(status);var bar=new ProgressBar {Style=ProgressBarStyle.Marquee};bar.SetBounds(18,120,524,20);Controls.Add(bar);close.Text="Close";close.Enabled=false;close.SetBounds(440,153,100,30);Controls.Add(close);close.Click+=(s,e)=>Close();FormClosing+=(s,e)=>{if(!done)e.Cancel=true;};worker.DoWork+=(s,e)=>{e.Result=UninstallProgram.Remove(root,backup,integrations);};worker.RunWorkerCompleted+=(s,e)=>{done=true;close.Enabled=true;bar.Style=ProgressBarStyle.Blocks;bar.Value=e.Error==null?100:0;if(e.Error==null){status.Text="Cross Hermit English was removed. Your files are preserved here:\n"+backup;if(result!=null)Core.Write(result,e.Result);}else{status.Text=e.Error.Message;if(result!=null)Core.Write(result,new {passed=false,error=e.Error.Message});}};Shown+=(s,e)=>worker.RunWorkerAsync();}
 }
}
